import random

# Build edge list
edges = []
# Within cliques
for g in range(6):
    for i in range(3):
        for j in range(i+1, 3):
            edges.append((g*3+i, g*3+j))
# Between consecutive cliques
for g in range(5):
    for i in range(3):
        edges.append((g*3+i, (g+1)*3+i))

print(f"Number of edges: {len(edges)}")

def check_solution(labels):
    # labels is list of 18 ints
    if len(set(labels)) != 18:
        return False
    if any(l < 0 or l > 33 for l in labels):
        return False
    diffs = set()
    for u, v in edges:
        d = abs(labels[u] - labels[v])
        if d < 1 or d > 33:
            return False
        if d in diffs:
            return False
        diffs.add(d)
    return len(diffs) == 33

def random_search(iterations):
    for _ in range(iterations):
        labels = random.sample(range(34), 18)
        if check_solution(labels):
            return labels
    return None

# Try random search
for trial in range(5):
    result = random_search(20000)
    if result:
        print(f"Found: {result}")
        break
else:
    print("No random solution found in 5 trials of 20000 each")
